// By value: sources may be {url, ...} objects, which includes() compares by reference.
const keepsAll = (newList, oldList) => {
  const have = new Set((newList || []).map((x) => JSON.stringify(x)));
  return (oldList || []).every((x) => have.has(JSON.stringify(x)));
};

