/bin/zsh -lc "node --input-type=module - <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
const kbPath = 'server/kristy_perimeter_kb.json';
const raw = readFileSync(kbPath, 'utf8');
const kb = JSON.parse(raw);
assert.equal(raw, JSON.stringify(kb, null, 2) + '\\n');
const ids = ['egg_duck_quail', 'label_cage_free', 'label_pasture_raised_feed'];
const old = new Map(ids.map(id => [id, structuredClone(kb.entries.find(e => e.id === id))]));
const card = id => kb.entries.find(e => e.id === id);
const source = (file, name) => {
  const text = readFileSync("'`docs/sources/concerns/dairy_eggs_packaging/${file}.md`, '"'utf8');
  const url = text.match(/"'^url:'"\\s*(\\S+)/m)?.[1];
  assert.ok(url, "'`${file} has no archived URL`);
  return { name, url };
};
const feedSource = source('"'cornucopia-egg-scorecard-criteria', 'The Cornucopia Institute: Organic Egg Scorecard Criteria');
const labelSource = source('cr-egg-carton-labels', 'Consumer Reports: Egg Carton Labels Explained');
const vegetarianSource = source('100daysofrealfood-egg-labels', '100 Days of Real Food: Egg Labels: What To Look For');
const gloss = 'Pasture-raised means time outdoors on pasture, audited only with a certifier’s seal. Organic means certified organic feed and outdoor access.';

const duck = card('egg_duck_quail');
duck.decision = 'Pasture-raised duck or quail eggs with organic feed.';
duck.buying_tips.unshift('Look for printed soy-free or corn-free feed; otherwise choose organic feed.');
duck.cart_pick = 'Pasture-raised organic duck or quail eggs';
duck.pick_steps.unshift('Read the label for soy-free or corn-free feed; next, organic.');
duck.tier_note = "'`${gloss} ${duck.tier_note}`;
duck.sources.push(feedSource);

const cage = card('"'label_cage_free');
cage.decision = 'Pasture-raised eggs with printed soy-free or corn-free feed.';
cage.short_answer = 'None of cage-free, free-range or pasture-raised says what the hen ate. Find soy-free or corn-free feed printed outright. Next choose pasture-raised organic, then organic, then cage-free.';
cage.buying_tips.unshift('Cage-free, free-range and pasture-raised say nothing about the hen’s feed.');
cage.buying_tips.push(
  'Look for soy-free or corn-free feed printed outright alongside pasture-raised and a certifier’s seal.',
  'Next choose pasture-raised organic, then organic, then cage-free. Organic feed can still contain soy and corn.',
);
cage.pick_steps.unshift('Find soy-free or corn-free feed printed outright on the carton.');
cage.pick_steps.push('Next: pasture-raised organic, then organic, then cage-free.');
cage.tier_note = gloss;
cage.sources.push(feedSource, labelSource);

const pasture = card('label_pasture_raised_feed');
pasture.decision = 'Pasture-raised eggs with soy-free or corn-free feed printed outright.';
pasture.short_answer = '“Vegetarian fed” means the feed contains no animal byproducts. It says nothing about pasture or time outdoors. Hens on pasture eat insects and forage. Look for pasture-raised with a printed feed claim.';
pasture.detail = pasture.detail
  .replace('“Certified organic” is the one term that does reach feed', '“Certified organic” reaches feed')
  .replace('If feed is what you care about, the word to look for is “soy-free”; it has to be printed, because nothing else on the carton implies it.', 'Look for pasture-raised with “soy-free” or “corn-free” feed printed outright. Next choose pasture-raised organic, then organic, then cage-free. “Vegetarian fed” means no animal byproducts in the supplied feed. It says nothing about pasture or time outdoors and does not tell whether a hen foraged. Hens on pasture eat insects and forage.');
pasture.kristy_take = 'Pasture-raised with a printed soy-free or corn-free feed claim. Next, pasture-raised organic, then organic, then cage-free. “Vegetarian fed” describes the supplied feed. It does not say whether the hen went outdoors.';
pasture.buying_tips[2] = 'Look for pasture-raised plus “soy-free” or “corn-free” feed printed explicitly.';
pasture.buying_tips.push(
  'Next choose pasture-raised organic, then organic, then cage-free.',
  '“Vegetarian fed” means no animal byproducts in the feed. It says nothing about pasture or time outdoors.',
  'Hens on pasture eat insects and forage. Read the feed claim separately from the outdoor claim.',
);
pasture.watch_out.push('“Vegetarian fed” says nothing about pasture or time outdoors.');
pasture.pick_steps[0] = 'Find pasture-raised eggs with “soy-free” or “corn-free” feed printed on the carton.';
pasture.pick_steps[1] = 'Next choose pasture-raised organic, then organic, then cage-free.';
pasture.science = 'Cage-free, free-range and pasture-raised describe space. Most pasture-raised hens still eat soy and corn. USDA has no regulatory definition of pasture-raised; certifiers set outdoor requirements. Organic requires organic feed, usually soy and corn. It describes how feed was grown. “Vegetarian fed” means no animal byproducts in the feed, with no promise about outdoor time. Hens on pasture eat insects and forage.';
pasture.sources.push(feedSource, vegetarianSource);

let pins = readFileSync('server/test/acceptance/twoLinePin.js', 'utf8');
for (const id of ids) {
  const pattern = new RegExp("'`  "${id}": ('"\\\\{[\\\\s\\\\S]*?\\\\n  \\\\}),"'`);
  const match = pins.match(pattern);
  assert.ok(match, `missing ${id} pin`);
  const pin = JSON.parse(match[1]);
  for (const [key, value] of Object.entries(card(id))) {
    if (JSON.stringify(value) !== JSON.stringify(old.get(id)[key])) pin[key] = value;
  }
  const replacement = JSON.stringify(pin, null, 2).split('"'\\n').map((line, i) => i ? "'`  ${line}` : `  "${id}": ${line}`).join('"'\\n') + ',';
  pins = pins.replace(pattern, () => replacement);
}
pins = pins.replace('// concernDeli.test.js owns the new URLs.', '// concernDeli.test.js and concernEggs.test.js own the new URLs.');
pins = pins.replace(\"'pick_jerky', 'pork_cuts_and_enhanced']);\", \"'pick_jerky', 'pork_cuts_and_enhanced', 'egg_duck_quail', 'label_cage_free', 'label_pasture_raised_feed']);\");
assert.ok(pins.includes(\"'egg_duck_quail', 'label_cage_free', 'label_pasture_raised_feed']\"));

const actions = {
  egg_duck_quail: 'Read the feed claim and check for clean, uncracked shells.',
  label_cage_free: 'Find the welfare certifier’s seal, then read the feed claim.',
  label_pasture_raised_feed: 'Read both sides of the carton for the ration and outdoor claims.',
};
let review = readFileSync('docs/do-lines-review.md', 'utf8');
for (const id of ids) {
  const line = review.split('\\n').find(line => line.startsWith("'`| '"\\"'`${id}'"\\"'` |`));
  assert.ok(line, `missing ${id} review row`);
  const cells = line.split('"'|');
  cells[3] = "'` ${card(id).decision} `;
  cells[4] = ` ${actions[id]} `;
  review = review.replace(line, cells.join('"'|'));
}
writeFileSync(kbPath, JSON.stringify(kb, null, 2) + '\\n');
writeFileSync('server/test/acceptance/twoLinePin.js', pins);
writeFileSync('docs/do-lines-review.md', review);
for (const id of ids) console.log("'`${id}: ${Object.keys(card(id)).filter(key => JSON.stringify(card(id)[key]) !== JSON.stringify(old.get(id)[key])).join('"', ')}"'`);
NODE'

